        box-shadow: 0 3px 10px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.04);
      }
      :root[data-theme='dark'] .comment-badge { background: rgba(240, 170, 196, 0.14); }
      :root[data-theme='dark'] .option-btn { border-color: rgba(240, 170, 196, 0.16); background: rgba(255, 255, 255, 0.04); box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25); }
