      :root[data-theme='dark'] .option-btn.is-selected { border-color: rgba(240, 170, 196, 0.46); background: rgba(255, 255, 255, 0.1); }
      :root[data-theme='dark'] .option-index { border-color: rgba(240, 170, 196, 0.22); background: linear-gradient(145deg, #3a2932, #31232a); box-shadow: none; }
